import "server-only";

import type { FullVerse } from "./gita-types";
import data from "./gita.json";

/**
 * The complete Bhagavad Gita: 700 verses plus the 13.0 prelude.
 * Generated by scripts/build-gita.ts. Server-only so the ~450 KB of text never
 * ships in a client bundle.
 */
export const allVerses = data as FullVerse[];

const byId = new Map(allVerses.map((v, i) => [v.id, i]));

export function getFullVerse(id: string): FullVerse | undefined {
  const i = byId.get(id);
  return i === undefined ? undefined : allVerses[i];
}

export function chapterVerses(chapter: number): FullVerse[] {
  return allVerses.filter((v) => v.chapter === chapter);
}

export function neighbours(id: string): { prev?: FullVerse; next?: FullVerse } {
  const i = byId.get(id);
  if (i === undefined) return {};
  return { prev: allVerses[i - 1], next: allVerses[i + 1] };
}

export const TRANSLATION_CREDIT =
  "Translation adapted from Shri Purohit Swami (1935), public domain.";
